    raise exception '% % is still referenced as a subject by community.views', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from events.subjects where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by events.subjects', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from filesystem.contents where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by filesystem.contents', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from filesystem.media where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by filesystem.media', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from legal.effects where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by legal.effects', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from source.citations where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by source.citations', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from source.relationships where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by source.relationships', qualified, old.id using errcode = 'foreign_key_violation';
